// Records which OpenCode session started which, so agentview can show a manager
// session's spawned sessions indented under it.
//
// OpenCode's own parent_id is NOT used: it hides a child from the session list
// and folds its status into the parent. Links go to an append-only file instead,
// one JSON object per line, which agentview rereads when its mtime changes:
//   ~/.local/state/agentview/opencode/session-parents.jsonl
//   {"child":"ses_..","parent":"ses_..","at":1760000000000}
//
// Detection needs no database and no I/O on the hot path. A session that spawns
// another does it from a shell (a script that calls the server API, or
// opencode-bg.sh) and the new session's id shows up in that command's output.
// So: remember top-level sessions created in the last two minutes, and when a
// bash result contains one of those ids, the session that ran the command is
// its parent. The window keeps later mentions (one session messaging another,
// a listing of sessions) from creating links.
import { appendFileSync, existsSync, mkdirSync, readFileSync } from "node:fs"
import { homedir } from "node:os"
import { dirname, join } from "node:path"

const WINDOW_MS = 2 * 60 * 1000
const ID = /ses_[A-Za-z0-9]+/g

function linksFile() {
  const state = process.env.XDG_STATE_HOME?.startsWith("/")
    ? process.env.XDG_STATE_HOME
    : join(homedir(), ".local", "state")
  return join(state, "agentview", "opencode", "session-parents.jsonl")
}

function loadLinked(path) {
  const linked = new Set()
  if (!existsSync(path)) return linked
  for (const line of readFileSync(path, "utf8").split("\n")) {
    try {
      const child = JSON.parse(line)?.child
      if (typeof child === "string") linked.add(child)
    } catch {}
  }
  return linked
}

export const SpawnedSessions = async () => {
  const path = linksFile()
  const linked = loadLinked(path)
  // id -> created time, only top-level sessions (a task subagent has a parentID
  // and is not shown as its own row).
  const recent = new Map()
  const parents = new Map()

  function root(id) {
    let current = id
    for (let hops = 0; hops < 8; hops++) {
      const parent = parents.get(current)
      if (!parent) return current
      current = parent
    }
    return current
  }

  function prune(now) {
    for (const [id, at] of recent) if (now - at > WINDOW_MS) recent.delete(id)
  }

  return {
    event: async ({ event }) => {
      if (event.type !== "session.created") return
      const info = event.properties?.info
      if (!info?.id) return
      if (info.parentID) {
        parents.set(info.id, info.parentID)
        return
      }
      const now = Date.now()
      prune(now)
      recent.set(info.id, now)
    },
    "tool.execute.after": async (input, output) => {
      if (input.tool !== "bash" || !input.sessionID) return
      const now = Date.now()
      prune(now)
      if (recent.size === 0) return
      const text = `${output?.output ?? ""}\n${output?.metadata?.output ?? ""}`
      const parent = root(input.sessionID)
      const lines = []
      for (const id of new Set(text.match(ID) ?? [])) {
        if (id === parent || id === input.sessionID) continue
        if (!recent.has(id) || linked.has(id)) continue
        linked.add(id)
        lines.push(JSON.stringify({ child: id, parent, at: now }))
      }
      if (lines.length === 0) return
      try {
        mkdirSync(dirname(path), { recursive: true })
        appendFileSync(path, lines.join("\n") + "\n")
      } catch {}
    },
  }
}
